def R(code, name, short, pop, pcrel, dev, unrest, auto, reg, tr, sec, infra, edu, health, env, mix, desc, E, Ecal=None):
    return dict(code=code, name=name, short=short, pop=pop, pcrel=pcrel, dev=dev, unrest=unrest, auto=auto, reg=reg, tr=tr,
                sec={"ind": sec[0], "agr": sec[1], "srv": sec[2], "res": sec[3]}, infra=infra, edu=edu, health=health, env=env, mix=mix, desc=desc, E=E, Ecal=Ecal)


# Список «Сербия против насилия» (2023) делим между слотами по фракциям: ССП 19/65, ЗЛФ+ЭВ 15/65 (в Белграде и Нови-Саде больше), ДС 8/65, остальное (НДС, СРЦЕ) — «прочие».
def E23(sns, spn, sps, nada, mi, mino, oth, zlf=15.0 / 65):
    ssp, ds = 19.0 / 65, 8.0 / 65
    rest = max(0.0, 1.0 - ssp - ds - zlf)
    return [sns, sps, spn * ssp, spn * zlf, nada, mi, spn * rest + oth, spn * ds, mino, 0.0]


def Ecal(row, stud):
    """для калибровки: доли 2023 года + региональный профиль «Студенческого списка» (оценка по опросам и картам протестов 2025 года)"""
    r = list(row); r[9] = stud
    return r


